//! Phase 6 exit: conformance of the DSP and matrix crates against known-good
//! outputs.
//!
//! The expected values live in `tests/golden/dsp_golden.rs`, generated by
//! `tests/golden/gen_dsp_golden.py` from scipy, numpy and exact integer
//! arithmetic. None of them come from the crates under test, so a bug that
//! the crates' own scalar and SIMD paths share still shows up here.

use tpt_simd::convolve::{
    convolve_1d_f32, convolve_1d_output_len, convolve_1d_scalar_f32, fir_filter_i16,
};
use tpt_simd::interpolate::{
    interpolate_cubic_f32, interpolate_cubic_scalar_f32, interpolate_lanczos_f32,
    interpolate_lanczos_scalar_f32, interpolate_linear_f32, interpolate_linear_simd_f32,
};
use tpt_simd::matrix::{mat3x3_inverse_f32, mat4x4_mul_f32};
use tpt_simd::select::{select_lanes_f32, try_select_from_slice_i32};
use tpt_simd::window::{
    apply_window_f32, apply_window_scalar_f32, blackman_window_into_f32, hamming_window_into_f32,
    hanning_window_into_f32, kaiser_window_into_f32,
};
use tpt_simd::{F32x8, I32x8};

include!("golden/dsp_golden.rs");

/// Tolerance for the cosine-sum windows (the crate documents about 3e-6
/// absolute error against f64).
const COS_SUM_TOL: f32 = 5e-6;
/// Tolerance for Kaiser (computed in f64, rounded to f32).
const KAISER_TOL: f32 = 1e-6;

fn assert_close(label: &str, got: &[f32], want: &[f32], tol: f32) {
    assert_eq!(got.len(), want.len(), "{label}: length");
    for (i, (g, w)) in got.iter().zip(want).enumerate() {
        assert!(
            (g - w).abs() <= tol,
            "{label}[{i}]: got {g}, want {w} (tol {tol})"
        );
    }
}

fn assert_close_mat<const R: usize, const C: usize>(
    label: &str,
    got: &[[f32; C]; R],
    want: &[[f32; C]; R],
    tol: f32,
) {
    for r in 0..R {
        assert_close(&format!("{label}[{r}]"), &got[r], &want[r], tol);
    }
}

macro_rules! window_case {
    ($fill:ident, $n:literal, $want:ident, $tol:expr) => {{
        let mut out = [0.0f32; $n];
        $fill(&mut out);
        assert_close(
            concat!(stringify!($fill), " n=", stringify!($n)),
            &out,
            $want,
            $tol,
        );
    }};
}

#[test]
fn hamming_matches_scipy() {
    window_case!(hamming_window_into_f32, 1, HAMMING_1, COS_SUM_TOL);
    window_case!(hamming_window_into_f32, 2, HAMMING_2, COS_SUM_TOL);
    window_case!(hamming_window_into_f32, 3, HAMMING_3, COS_SUM_TOL);
    window_case!(hamming_window_into_f32, 8, HAMMING_8, COS_SUM_TOL);
    window_case!(hamming_window_into_f32, 17, HAMMING_17, COS_SUM_TOL);
    window_case!(hamming_window_into_f32, 64, HAMMING_64, COS_SUM_TOL);
}

#[test]
fn hann_matches_scipy() {
    window_case!(hanning_window_into_f32, 1, HANN_1, COS_SUM_TOL);
    window_case!(hanning_window_into_f32, 2, HANN_2, COS_SUM_TOL);
    window_case!(hanning_window_into_f32, 3, HANN_3, COS_SUM_TOL);
    window_case!(hanning_window_into_f32, 8, HANN_8, COS_SUM_TOL);
    window_case!(hanning_window_into_f32, 17, HANN_17, COS_SUM_TOL);
    window_case!(hanning_window_into_f32, 64, HANN_64, COS_SUM_TOL);
}

#[test]
fn blackman_matches_scipy() {
    window_case!(blackman_window_into_f32, 1, BLACKMAN_1, COS_SUM_TOL);
    window_case!(blackman_window_into_f32, 2, BLACKMAN_2, COS_SUM_TOL);
    window_case!(blackman_window_into_f32, 3, BLACKMAN_3, COS_SUM_TOL);
    window_case!(blackman_window_into_f32, 8, BLACKMAN_8, COS_SUM_TOL);
    window_case!(blackman_window_into_f32, 17, BLACKMAN_17, COS_SUM_TOL);
    window_case!(blackman_window_into_f32, 64, BLACKMAN_64, COS_SUM_TOL);
}

#[test]
fn kaiser_beta8_matches_scipy() {
    let mut out = [0.0f32; 1];
    kaiser_window_into_f32(&mut out, 8.0);
    assert_close("kaiser n=1", &out, KAISER8_1, KAISER_TOL);

    let mut out = [0.0f32; 2];
    kaiser_window_into_f32(&mut out, 8.0);
    assert_close("kaiser n=2", &out, KAISER8_2, KAISER_TOL);

    let mut out = [0.0f32; 3];
    kaiser_window_into_f32(&mut out, 8.0);
    assert_close("kaiser n=3", &out, KAISER8_3, KAISER_TOL);

    let mut out = [0.0f32; 8];
    kaiser_window_into_f32(&mut out, 8.0);
    assert_close("kaiser n=8", &out, KAISER8_8, KAISER_TOL);

    let mut out = [0.0f32; 17];
    kaiser_window_into_f32(&mut out, 8.0);
    assert_close("kaiser n=17", &out, KAISER8_17, KAISER_TOL);

    let mut out = [0.0f32; 64];
    kaiser_window_into_f32(&mut out, 8.0);
    assert_close("kaiser n=64", &out, KAISER8_64, KAISER_TOL);
}

