// --- Special values: SIMD paths must match their scalar references bit for
// bit, including NaN, infinities, signed zero, subnormals, empty inputs and
// lengths that are not a multiple of the lane count.

/// Bitwise equality, with any two NaNs treated as equal (payloads are not
/// specified by IEEE 754).
fn same_f32(a: f32, b: f32) -> bool {
    (a.is_nan() && b.is_nan()) || a.to_bits() == b.to_bits()
}

/// A deterministic mix of ordinary values and special values.
fn special_samples(n: usize) -> Vec<f32> {
    (0..n)
        .map(|i| match i % 11 {
            3 => f32::NAN,
            5 => f32::INFINITY,
            6 => f32::NEG_INFINITY,
            7 => -0.0,
            8 => f32::MIN_POSITIVE / 4.0,
            _ => (i as f32 * 0.37).sin() * 3.0,
        })
        .collect()
}

fn eight(v: Vec<f32>) -> F32x8 {
    F32x8::from_array(v.try_into().expect("eight lanes"))
}

fn assert_same_bits(label: &str, got: &[f32], want: &[f32]) {
    assert_eq!(got.len(), want.len(), "{label}: length");
    for (i, (g, w)) in got.iter().zip(want).enumerate() {
        assert!(same_f32(*g, *w), "{label}[{i}]: got {g:?}, want {w:?}");
    }
}

#[test]
fn convolve_special_values_match_scalar_bitwise() {
    // Lengths cover 1-element operands, sub-lane tails and multi-lane runs.
    for &(n, k) in &[
        (1usize, 1usize),
        (3, 2),
        (7, 5),
        (8, 8),
        (9, 3),
        (17, 4),
        (33, 9),
        (64, 1),
    ] {
        let input = special_samples(n);
        let kernel = special_samples(k);
        let mut got = vec![0.0; convolve_1d_output_len(n, k)];
        let mut want = vec![0.0; got.len()];
        convolve_1d_f32(&input, &kernel, &mut got);
        convolve_1d_scalar_f32(&input, &kernel, &mut want);
        assert_same_bits(&format!("convolve n={n} k={k}"), &got, &want);
    }
}

#[test]
fn convolve_empty_operands() {
    let mut out: [f32; 0] = [];
    convolve_1d_f32(&[], &[1.0], &mut out);
    convolve_1d_f32(&[1.0], &[], &mut out);
    assert_eq!(convolve_1d_output_len(0, 3), 0);
}

#[test]
fn interpolate_linear_special_values_match_scalar_bitwise() {
    let a = eight(special_samples(8));
    let b = eight(special_samples(16)[8..].to_vec());
    let t = eight(vec![
        0.0,
        0.25,
        0.5,
        1.0,
        -0.0,
        f32::NAN,
        2.0,
        f32::INFINITY,
    ]);
    let got = interpolate_linear_simd_f32(a, b, t);
    for l in 0..8 {
        let want = interpolate_linear_f32(a.0[l], b.0[l], t.0[l]);
        assert!(
            same_f32(got.0[l], want),
            "linear lane {l}: got {:?}, want {want:?}",
            got.0[l]
        );
    }
}

#[test]
fn interpolate_cubic_special_values_match_scalar_bitwise() {
    let a = eight(special_samples(8));
    let b = eight(special_samples(16)[8..].to_vec());
    let c = eight(special_samples(24)[16..].to_vec());
    let d = eight(special_samples(32)[24..].to_vec());
    let t = eight(vec![
        0.0,
        0.25,
        0.5,
        1.0,
        -0.0,
        f32::NAN,
        2.0,
        f32::INFINITY,
    ]);
    let got = interpolate_cubic_f32(a, b, c, d, t);
    for l in 0..8 {
        let want = interpolate_cubic_scalar_f32(a.0[l], b.0[l], c.0[l], d.0[l], t.0[l]);
        assert!(
            same_f32(got.0[l], want),
            "cubic lane {l}: got {:?}, want {want:?}",
            got.0[l]
        );
    }
}

#[test]
fn interpolate_lanczos_matches_scalar_within_documented_tolerance() {
    // The SIMD path is not bit-identical to the scalar one (the scalar path
    // fuses multiply-add; the SIMD path does not), so this checks the
    // documented ~1e-5 agreement on finite inputs.
    let a = 3;
    let samples: Vec<F32x8> = (0..2 * a)
        .map(|j| {
            eight(
                (0..8)
                    .map(|l| ((j * 8 + l) as f32 * 0.61).cos() * 2.0)
                    .collect(),
            )
        })
        .collect();
    let t = eight(vec![0.0, 0.1, 0.25, 0.5, 0.75, 0.9, 0.99, 0.37]);
    let got = interpolate_lanczos_f32(&samples, t, a);
    for l in 0..8 {
        let lane: Vec<f32> = samples.iter().map(|v| v.0[l]).collect();
        let want = interpolate_lanczos_scalar_f32(&lane, t.0[l], a);
        assert!(
            (got.0[l] - want).abs() <= 1e-5 * 2.0,
            "lanczos lane {l}: got {}, want {want}",
            got.0[l]
        );
    }
}

#[test]
fn interpolate_lanczos_non_finite_lanes_stay_non_finite() {
    // Known difference, not checked for equality: with an infinite sample the
    // SIMD path can return NaN where the scalar path returns -inf (or the
    // reverse). Both must still be non-finite, so a poisoned lane is never
    // reported as a finite value. See todo.md (Phase 6, interpolate).
    let a = 3;
    let samples: Vec<F32x8> = (0..2 * a)
        .map(|j| eight(special_samples(8 + j)[j..j + 8].to_vec()))
        .collect();
    let t = eight(vec![
        0.0,
        0.25,
        0.5,
        0.75,
        -0.0,
        f32::NAN,
        0.9,
        f32::INFINITY,
    ]);
    let got = interpolate_lanczos_f32(&samples, t, a);
    for l in 0..8 {
        let lane: Vec<f32> = samples.iter().map(|v| v.0[l]).collect();
        let want = interpolate_lanczos_scalar_f32(&lane, t.0[l], a);
        if !lane.iter().any(|v| !v.is_finite()) && t.0[l].is_finite() {
            continue;
        }
        assert!(
            !got.0[l].is_finite(),
            "lanczos lane {l}: SIMD finite {}",
            got.0[l]
        );
        assert!(!want.is_finite(), "lanczos lane {l}: scalar finite {want}");
    }
}

#[test]
fn window_apply_special_values_match_scalar_bitwise() {
    for n in [1usize, 2, 7, 8, 9, 15, 16, 17] {
        let window = special_samples(n)
            .iter()
            .map(|v| v.abs())
            .collect::<Vec<_>>();
        let data = special_samples(n + 3)[3..].to_vec();
        let mut got = data.clone();
        let mut want = data;
        apply_window_f32(&mut got, &window);
        apply_window_scalar_f32(&mut want, &window);
        assert_same_bits(&format!("apply_window n={n}"), &got, &want);
    }
}

#[test]
fn select_lanes_special_values_pass_through_bitwise() {
    // A permutation must not alter any bit pattern, NaN and -0.0 included.
    let v = eight(special_samples(8));
    let idx = I32x8::from_array([7, 0, 3, 3, 5, 6, 1, 4]);
    let got = select_lanes_f32(v, idx);
    for k in 0..8 {
        let want = v.0[idx.0[k] as usize];
        assert!(
            same_f32(got.0[k], want),
            "select lane {k}: got {:?}, want {want:?}",
            got.0[k]
        );
    }
}

#[test]
fn select_from_empty_slice_is_none() {
    assert!(try_select_from_slice_i32(&[], I32x8::splat(0)).is_none());
}
